export const locales = ["ru", "en", "uk", "sr-Latn", "zh-Hans"] as const;
export type Locale = typeof locales[number];
export type MessageKey = keyof typeof ru;
export const messages: Record<Locale, Record<MessageKey, string>> = { ru, en, uk, "sr-Latn": srLatn, "zh-Hans": zhHans };

export function translate(locale: Locale, key: MessageKey, values: Record<string, string | number> = {}) {
  const number = new Intl.NumberFormat(locale);
  return Object.entries(values).reduce((text, [name, value]) => text.replaceAll(`{${name}}`, typeof value === "number" ? number.format(value) : value), messages[locale][key]);
}

export function formatItemCount(locale: Locale, count: number) {
  const rule = new Intl.PluralRules(locale).select(count);
  const forms: Record<Locale, Partial<Record<Intl.LDMLPluralRule, string>>> = {
    ru: { one: "вещь", few: "вещи", many: "вещей", other: "вещей" }, en: { one: "item", other: "items" },
    uk: { one: "предмет", few: "предмети", many: "предметів", other: "предметів" }, "sr-Latn": { one: "predmet", few: "predmeta", other: "predmeta" }, "zh-Hans": { other: "件物品" },
  };
  return `${new Intl.NumberFormat(locale).format(count)} ${forms[locale][rule] ?? forms[locale].other}`;
}

export function formatCollectionCount(locale: Locale, count: number) {
  const rule = new Intl.PluralRules(locale).select(count);
  const forms: Record<Locale, Partial<Record<Intl.LDMLPluralRule, string>>> = {
    ru: { one: "коллекция", few: "коллекции", many: "коллекций", other: "коллекций" }, en: { one: "collection", other: "collections" },
    uk: { one: "колекція", few: "колекції", many: "колекцій", other: "колекцій" }, "sr-Latn": { one: "kolekcija", few: "kolekcije", other: "kolekcija" }, "zh-Hans": { other: "个收藏集" },
  };
  return `${new Intl.NumberFormat(locale).format(count)} ${forms[locale][rule] ?? forms[locale].other}`;
}

export function formatDate(locale: Locale, value: string) {
  const date = new Date(value);
  return Number.isNaN(date.valueOf()) ? value : new Intl.DateTimeFormat(locale, { dateStyle: "medium" }).format(date);
}
